import{_ as e,c as t,o as s,ag as i}from"./chunks/framework.C86mscM5.js";const m=JSON.parse('{"title":"SBOM 与供应链证明","description":"","frontmatter":{},"headers":[],"relativePath":"devops/security-reliability/sbom.md","filePath":"devops/security-reliability/sbom.md","lastUpdated":1788092044000}'),l={name:"devops/security-reliability/sbom.md"};function n(o,a,r,p,c,d){return s(),t("div",null,a[0]||(a[0]=[i(`<h1 id="sbom-与供应链证明" tabindex="-1">SBOM 与供应链证明 <a class="header-anchor" href="#sbom-与供应链证明" aria-label="Permalink to &quot;SBOM 与供应链证明&quot;">​</a></h1><p>SBOM（Software Bill of Materials）是某个制品包含的软件组件、版本和关系清单。它用于回答“这个已发布版本是否包含受影响组件”，不能替代漏洞扫描。</p><h2 id="格式与生成" tabindex="-1">格式与生成 <a class="header-anchor" href="#格式与生成" aria-label="Permalink to &quot;格式与生成&quot;">​</a></h2><p>常见机器可读格式包括 SPDX 和 CycloneDX。SBOM 应在 CI 中针对最终制品生成，而不是只扫描源码清单；容器需要覆盖操作系统包和应用依赖。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Commit → Build → Artifact/Image</span></span>
<span class="line"><span>                  ├─ SBOM</span></span>
<span class="line"><span>                  ├─ Vulnerability Report</span></span>
<span class="line"><span>                  └─ Signature/Provenance</span></span></code></pre></div><p>Syft、Trivy 以及语言生态工具可以生成 SBOM。选择工具后固定版本并验证输出包含直接依赖、传递依赖和基础镜像组件。</p><h2 id="保存与关联" tabindex="-1">保存与关联 <a class="header-anchor" href="#保存与关联" aria-label="Permalink to &quot;保存与关联&quot;">​</a></h2><ul><li>SBOM 与制品 digest、Commit SHA、构建任务和发布日期关联。</li><li>作为发布制品保存到支持 OCI Artifact 的仓库或专用系统。</li><li>不覆盖历史 SBOM；设置至少覆盖制品支持周期的保留期。</li><li>漏洞公告出现后，通过 SBOM 反查受影响服务和部署环境。</li></ul><h2 id="签名与证明" tabindex="-1">签名与证明 <a class="header-anchor" href="#签名与证明" aria-label="Permalink to &quot;签名与证明&quot;">​</a></h2><p>Cosign 可对镜像和相关 Artifact 签名；构建来源证明描述由什么源码、流程和构建器生成制品；SLSA 提供供应链完整性框架。部署准入应验证签名身份、仓库、工作流和制品摘要，而不是只检查“存在签名”。</p><p>VEX 可表达某漏洞为何不影响特定产品，但必须包含依据、责任人和复审条件，不能用来批量消除告警。</p>`,11)]))}const u=e(l,[["render",n]]);export{m as __pageData,u as default};
